/**
 * Represents whether a block collides with the camera in Minecraft Legends.
 *
 * This type specifies whether the block interacts with the camera during gameplay. It allows developers
 * to control camera behavior when interacting with blocks.
 *
 * type {boolean} BlockCameraCollisionType
 * @category Block Configuration
 * @example
 * const cameraCollision: BlockCameraCollisionType = true;
 * @remarks
 * Properly configuring this setting ensures that camera interactions with blocks are consistent.
 * Misconfigured settings may lead to visual or functional inconsistencies.
 */
declare type BlockCameraCollisionType = boolean;
